package com.medilink.store.entity;
import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import java.sql.Types; import java.util.UUID;
@Entity @Table(name="Stores") public class Store { @Id @JdbcTypeCode(Types.VARCHAR) @Column(name="Id", columnDefinition="char(36)") private UUID id; @Column(name="Name") private String name; @Column(name="Address") private String address; @JdbcTypeCode(Types.VARCHAR) @Column(name="StoreOwnerProfileId", columnDefinition="char(36)") private UUID storeOwnerProfileId; public Store(){} public Store(String name,String address,UUID storeOwnerProfileId){this(UUID.randomUUID(),name,address,storeOwnerProfileId);} public Store(UUID id,String name,String address,UUID storeOwnerProfileId){this.id=id;this.name=name;this.address=address;this.storeOwnerProfileId=storeOwnerProfileId;} public UUID getId(){return id;} public String getName(){return name;} public String getAddress(){return address;} }
